# -*- coding: utf-8 -*-
P1 = "Cari kalimat yang menyatakan pendapat/alasan penulis (〜からだ、〜と思う、しかし〜)."
P2 = "Cocokkan setiap pilihan dengan teks; pilihan yang menambahkan hal yang tidak ada di teks adalah salah."
JN = 'Teks pendek (内容理解・短文)'
W = ['Tidak disebut dalam teks.', 'Tidak sesuai dengan isi teks.', 'Bertentangan dengan isi teks.']
def T(jp, idt, q, opts, ans, alasan, bukti, poin=P1):
    return dict(slot='tan', jenis=JN, jp=jp, id=idt, qs=[(q, opts, ans, alasan, bukti, W, poin)])
B = [
 T('最近、私は通勤の時間を使って英語の勉強を始めた。電車の中で動画を見ながら聞くだけなので、疲れている日でも続けられる。始めて三か月だが、簡単な会話なら聞き取れるようになってきた。','Belakangan saya mulai belajar bahasa Inggris memanfaatkan waktu berangkat kerja. Cukup mendengar sambil menonton video di kereta, jadi bisa lanjut walau lelah. Sudah tiga bulan dan percakapan sederhana mulai terdengar.',
   '「私」が英語の勉強を続けられる理由は何か。',['聞くだけで疲れていても続けられるから','先生が毎日来るから','試験が近いから','お金がかからないから'],0,'Karena cukup mendengar.','聞くだけなので、疲れている日でも続けられる'),
 T('駅前のパン屋が来月閉店することになった。四十年続いた店で、私も子どものころからよく通った。店主は「年を取って体がつらくなった」と話している。最後の日まで、いつもの味を出すそうだ。','Toko roti di depan stasiun akan tutup bulan depan. Sudah 40 tahun dan saya sering ke sana sejak kecil. Pemiliknya bilang badan sudah berat karena tua. Sampai hari terakhir akan menyajikan rasa seperti biasa.',
   'パン屋が閉店する理由は何か。',['店主が年を取って体がつらくなったから','お客が減ったから','店が古くなったから','駅が工事に入るから'],0,'Pemilik tua dan badan berat.','年を取って体がつらくなった',P2),
 T('山田さんは、新しい部署に移ってから、毎日帰りが遅くなった。以前は六時に帰れたが、今は仕事が多くて九時を過ぎる。それでも「やりがいがある」と笑顔で話している。','Setelah pindah ke departemen baru Yamada pulang makin larut. Dulu bisa pulang jam enam, kini lewat jam sembilan karena kerjaan banyak. Tapi ia berkata sambil tersenyum bahwa pekerjaannya bermakna.',
   '山田さんは今の仕事をどう思っているか。',['やりがいがあると思っている','つらいのでやめたいと思っている','簡単だと思っている','前の部署のほうがいいと思っている'],0,'Menganggapnya bermakna.','「やりがいがある」と笑顔で'),
 T('私の町では、毎月第一日曜日に「フリーマーケット」が開かれる。いらなくなった服や本を安く売ったり買ったりできる。売る人も買う人も楽しそうで、町の人が自然に話せる場にもなっている。','Di kota saya tiap Minggu pertama diadakan pasar loak. Bisa jual-beli baju dan buku bekas dengan murah. Penjual dan pembeli tampak senang dan jadi tempat warga mengobrol secara alami.',
   'このフリーマーケットについて、正しいものはどれか。',['町の人が話せる場にもなっている','毎週開かれる','新しい物だけ売る','お金がかかる'],0,'Menjadi tempat warga bicara.','町の人が自然に話せる場にもなっている',P2),
 T('先週、息子の運動会に行った。息子はかけっこで転んだが、すぐ立ち上がって最後まで走った。結果は最下位だったが、私は息子が誇らしくて、思わず大きな声で応援した。','Minggu lalu saya ke acara olahraga anak. Anak jatuh saat lomba lari tapi segera bangun dan berlari sampai akhir. Hasilnya terakhir tapi saya bangga dan tanpa sadar bersorak keras.',
   '「私」が誇らしく思ったのはなぜか。',['息子が転んでも最後まで走ったから','息子が一位になったから','息子が泣かなかったから','息子が先生にほめられたから'],0,'Karena anak berlari sampai akhir.','すぐ立ち上がって最後まで走った'),
 T('最近は、紙の本ではなく電子書籍を読む人が増えている。持ち運びが便利で、文字の大きさも変えられるからだ。しかし、私は紙をめくる感じが好きなので、やはり紙の本を買ってしまう。','Belakangan makin banyak orang membaca e-book daripada buku kertas. Praktis dibawa dan ukuran huruf bisa diubah. Tapi karena saya suka rasa membalik kertas, saya tetap membeli buku kertas.',
   '「私」はなぜ紙の本を買うのか。',['紙をめくる感じが好きだから','電子書籍が高いから','電子書籍が読みにくいから','店が近いから'],0,'Suka rasa membalik kertas.','紙をめくる感じが好きなので'),
 T('隣の家に新しい住人が引っ越してきた。挨拶に来た若い夫婦は、とても礼儀正しかった。小さなお菓子までもらって、私はいい人たちが来てくれてよかったと思った。','Tetangga baru pindah. Pasangan muda yang datang menyapa sangat sopan. Saya juga diberi sedikit kue, dan saya senang mereka orang baik.',
   '「私」は新しい隣人についてどう思ったか。',['いい人たちだと思った','うるさそうだと思った','冷たそうだと思った','よく知らない人だと思った'],0,'Orang baik.','いい人たちが来てくれてよかった'),
 T('日本の夏は湿度が高く、体の汗が乾きにくい。そのため、熱中症になる人が多い。水分をこまめにとることや、エアコンを上手に使うことが、予防のために大切だと言われている。','Musim panas Jepang lembap sehingga keringat sulit kering, sehingga banyak orang terkena heatstroke. Sering minum dan memakai AC dengan bijak penting sebagai pencegahan.',
   '熱中症を予防するために大切なことは何か。',['水分をこまめにとること','毎日運動すること','汗をかかないこと','外で長く過ごすこと'],0,'Sering minum.','水分をこまめにとること',P2),
 T('友人の誘いで、初めて登山をした。出発前は不安だったが、頂上から見た景色は想像以上に美しかった。疲れも忘れてしまい、また来たいと思うほどだった。','Atas ajakan teman, saya pertama kali mendaki gunung. Sebelum berangkat cemas, tapi pemandangan dari puncak lebih indah dari bayangan. Saya lupa lelah dan ingin datang lagi.',
   '「私」は登山のあとどう思ったか。',['また来たいと思った','もう行きたくないと思った','景色がつまらないと思った','疲れてもう歩けないと思った'],0,'Ingin datang lagi.','また来たいと思うほどだった'),
 T('この図書館は、午後八時まで開いているので、仕事の帰りに寄れて便利だ。ただし、日曜日は休みなので、日曜日に借りたい人は土曜日のうちに行く必要がある。','Perpustakaan ini buka sampai jam 8 malam jadi praktis mampir pulang kerja. Tapi hari Minggu tutup, jadi yang ingin meminjam Minggu harus datang Sabtu.',
   '日曜日に本を借りたい人はどうしなければならないか。',['土曜日のうちに借りに行く','日曜日の夜に行く','月曜日まで待つ','電話で予約する'],0,'Datang Sabtu.','土曜日のうちに行く必要がある',P2),
 T('私の祖母は九十歳だが、毎日自分で料理をしている。「作る人がいなくなったら、味が消えてしまう」と言って、私にも作り方を教えてくれる。私はそれを大切に覚えている。','Nenek saya berusia 90 tahun tapi masak sendiri tiap hari. Ia berkata jika yang membuat tiada rasanya hilang, maka mengajari saya cara membuatnya. Saya mengingatnya dengan hati-hati.',
   '祖母はなぜ「私」に作り方を教えるのか。',['作る人がいなくなったら味が消えてしまうから','料理が好きでないから','私が頼んだから','病気だから'],0,'Agar rasanya tidak hilang.','作る人がいなくなったら、味が消えてしまう'),
 T('最近は、駅や空港で外国語の案内が増えた。観光客が増えたことが理由だ。しかし、案内が多すぎて、かえって分かりにくいという声もある。必要な情報だけを分かりやすく示す工夫が求められている。','Belakangan petunjuk bahasa asing di stasiun dan bandara bertambah karena wisatawan meningkat. Tapi ada suara bahwa terlalu banyak justru membingungkan. Dibutuhkan upaya menampilkan hanya informasi perlu dengan jelas.',
   '案内について、どんな問題があると言っているか。',['多すぎて分かりにくい場合がある','外国語が間違っている','数が足りない','文字が小さい'],0,'Terlalu banyak dan membingungkan.','かえって分かりにくいという声もある',P2),
 T('母は、私が一人暮らしを始めてから、毎週のように荷物を送ってくる。中身は野菜や調味料だ。最初は「送りすぎだ」と思ったが、今は母の気持ちがありがたく感じられる。','Sejak saya hidup sendiri ibu hampir tiap minggu mengirim paket berisi sayur dan bumbu. Awalnya saya pikir terlalu banyak tapi sekarang bersyukur akan perasaannya.',
   '「私」は今、母の荷物をどう思っているか。',['母の気持ちがありがたいと思っている','送りすぎで迷惑だと思っている','もう送ってほしくないと思っている','中身が気に入らないと思っている'],0,'Bersyukur.','母の気持ちがありがたく感じられる'),
 T('このカフェは、コーヒーを飲みながら本が読めることで人気がある。店内の本は自由に読んでよいが、持ち帰ることはできない。気に入った本があれば、同じものを店内で買うこともできる。','Kafe ini populer karena bisa membaca buku sambil minum kopi. Buku di dalam bebas dibaca tapi tak boleh dibawa pulang. Jika ada yang disukai, bisa membeli yang sama di dalam toko.',
   'この店の本について、正しいものはどれか。',['店内で自由に読めるが、持ち帰れない','持ち帰ってもよい','読むのにお金がかかる','買うことはできない'],0,'Bebas dibaca tapi tak boleh dibawa pulang.','自由に読んでよいが、持ち帰ることはできない',P2),
 T('試験の前の日、私は夜遅くまで勉強したが、眠くて集中できなかった。次の日の試験でも頭が働かず、ミスをしてしまった。やはり、睡眠をしっかりとることが大切だと反省した。','Sehari sebelum ujian saya belajar sampai larut tapi mengantuk dan tidak fokus. Pada ujian berikutnya otak tak jalan dan saya berbuat salah. Saya menyesal dan sadar pentingnya tidur cukup.',
   '「私」は何が大切だと思ったか。',['睡眠をしっかりとること','夜遅くまで勉強すること','朝早く勉強すること','友達と勉強すること'],0,'Tidur cukup.','睡眠をしっかりとることが大切'),
 T('この地域では、毎年冬になると、雪かきのボランティアが活躍する。お年寄りの一人暮らしの家の前の雪をかく活動で、参加者は年々増えている。「顔を見て話す機会にもなる」と参加者は話す。','Di daerah ini tiap musim dingin relawan pembersih salju aktif. Mereka membersihkan salju di depan rumah lansia yang tinggal sendiri dan jumlahnya meningkat tiap tahun. Peserta bilang jadi kesempatan bertemu muka.',
   'ボランティア活動について、正しいものはどれか。',['参加者が年々増えている','参加者が減っている','夏に行われる','若者だけが参加する'],0,'Peserta bertambah.','参加者は年々増えている',P2),
 T('私は人と話すのが苦手で、会議でも発言できなかった。しかし、先輩が「間違えてもいいから、まず一言言ってみて」と言ってくれた。それから少しずつ、自分の意見が言えるようになった。','Saya tidak pandai bicara dan tak bisa berpendapat di rapat. Tapi senior berkata, boleh salah, coba katakan satu kalimat dulu. Sejak itu sedikit demi sedikit saya bisa menyatakan pendapat.',
   '「私」が意見を言えるようになったきっかけは何か。',['先輩の言葉','先生の授業','本を読んだこと','友達の相談'],0,'Kata-kata senior.','先輩が…言ってくれた'),
 T('新しいスマートフォンを買ったが、操作が複雑で使いこなせない。店員に聞いたところ、説明書を読まなくても、基本的な使い方なら動画で学べると教えてもらった。見てみると、とても分かりやすかった。','Saya membeli ponsel baru tapi operasinya rumit. Saat bertanya pada pegawai, diberi tahu cara dasar bisa dipelajari lewat video tanpa membaca manual. Ketika dilihat sangat mudah dimengerti.',
   '「私」はどうやって使い方を学んだか。',['動画を見て学んだ','説明書を読んだ','店で教えてもらった','友達に聞いた'],0,'Lewat video.','動画で学べると…見てみると、分かりやすかった'),
 T('駅の自動改札機は、一人ずつ通る仕組みだ。しかし、朝のラッシュのときは、後ろの人が急かすように近づいてくることがあって、慌てて間違える人も多い。落ち着いて通ることが大切だ。','Gerbang otomatis stasiun dilewati satu per satu. Tapi saat jam sibuk pagi kadang orang di belakang mendekat seperti mendesak sehingga banyak yang panik dan salah. Penting melewatinya dengan tenang.',
   'この文章で筆者が言いたいことは何か。',['落ち着いて通ることが大切だ','急いで通ったほうがいい','改札機をなくすべきだ','朝は電車に乗らないほうがいい'],0,'Lewati dengan tenang.','落ち着いて通ることが大切だ'),
 T('私は毎年、誕生日に自分への贈り物を買うことにしている。去年は靴、今年はかばんだった。高い物ではないが、一年頑張った自分をほめる気持ちで選んでいる。','Tiap tahun saya membeli hadiah untuk diri sendiri saat ulang tahun. Tahun lalu sepatu, tahun ini tas. Bukan barang mahal tapi dipilih dengan rasa memuji diri yang bekerja keras setahun.',
   '「私」が自分に贈り物を買う理由は何か。',['一年頑張った自分をほめるため','お金が余っているから','友達に勧められたから','店が安売りだから'],0,'Memuji diri sendiri.','自分をほめる気持ちで選んでいる'),
 T('この会社では、毎月一回、社員が自由に意見を出し合う会議を開いている。上司も部下も同じように発言できる雰囲気で、新しいアイデアが生まれることも多い。','Perusahaan ini mengadakan rapat sebulan sekali tempat karyawan bebas berbagi pendapat. Suasana membuat atasan dan bawahan bisa bicara setara sehingga sering lahir ide baru.',
   'この会議の特徴は何か。',['上司も部下も同じように発言できる','上司だけが話す','毎週開かれる','発言してはいけない'],0,'Atasan dan bawahan setara.','上司も部下も同じように発言できる雰囲気',P2),
 T('日本の食堂では、料理の見本が店の前に並べてあることが多い。外国から来た人でも、メニューが分からなくても見ただけで注文できるので、とても便利だと言われている。','Di rumah makan Jepang sering ada sampel masakan dipajang di depan toko. Orang asing yang tak paham menu pun bisa memesan hanya dengan melihat, sehingga dianggap sangat praktis.',
   '見本の利点は何か。',['見るだけで注文できる','料理が安くなる','待ち時間が短くなる','店員が必要なくなる'],0,'Bisa memesan hanya dengan melihat.','見ただけで注文できる',P2),
 T('山田さんは、ダイエットのために毎日歩くことにした。最初は三十分だったが、続けるうちに楽しくなって、今では一時間歩く。体重は三キロ減り、気分もよくなったそうだ。','Yamada memutuskan berjalan tiap hari untuk diet. Awalnya 30 menit tapi lama-lama menyenangkan sehingga kini satu jam. Berat turun tiga kilo dan suasana hati membaik.',
   '山田さんは今、一日にどのくらい歩いているか。',['一時間','三十分','二時間','十分'],0,'Satu jam.','今では一時間歩く',P2),
 T('私は小さいころから絵を描くのが好きだった。大人になって忙しくなり、しばらく描かなかったが、最近また始めた。休日に一枚描くだけで、心が落ち着くのを感じる。','Sejak kecil saya suka menggambar. Setelah dewasa sibuk dan lama tidak menggambar, tapi baru-baru ini mulai lagi. Hanya menggambar selembar di hari libur hati terasa tenang.',
   '「私」は絵を描くとどうなるか。',['心が落ち着く','疲れる','忙しくなる','お金が増える'],0,'Hati tenang.','心が落ち着くのを感じる'),
 T('先週、大雨のせいで電車が止まり、会社に行けなかった。連絡しようとしたが電話がつながらず、メールで上司に状況を伝えた。上司は「安全が一番だ」と返事をくれた。','Minggu lalu karena hujan deras kereta berhenti dan saya tak bisa ke kantor. Telepon tak tersambung jadi saya memberitahu atasan lewat email. Atasan membalas bahwa keselamatan yang utama.',
   '「私」はどうやって上司に連絡したか。',['メールで','電話で','直接会って','手紙で'],0,'Lewat email.','メールで上司に状況を伝えた'),
]
